const row = $input.item.json;

const clean = (value) => String(value ?? '').trim();
const isYes = (value) => clean(value).toLowerCase() === 'si';
const urlKeys = Array.from({ length: 12 }, (_, i) => 'URLs ' + (i + 1));
const photoUrls = urlKeys.map((key) => clean(row[key])).filter(Boolean);

const product = clean(row.Producto);
const description = clean(row['Descripci?n'] ?? row['Descripcion']);
const sizes = clean(row['Talles Disponibles']);
const price = clean(row.Precio);
const color = clean(row.Color);
const isOferta = isYes(row.Oferta);

const igCaption = [
  'Art. ' + product,
  description,
  'Numeracion: ~' + sizes + '~',
  price + ' Precio por Mayor',
  '',
  'Mas modelos disponibles en el catalogo',
  'https://fylmoda.com.ar/'
].join('\n');

const fbCaptionNormal = [
  'Art. ' + product,
  description,
  'Numeracion: ~' + sizes + '~',
  price + ' Precio por Mayor',
  '',
  'Modelo ya disponible en nuestro catalogo',
  'https://fylmoda.com.ar/'
].join('\n');

const fbCaptionOferta = [
  'OFERTA',
  'Art. ' + product,
  'Colores: ' + color,
  description,
  'Numeracion: ~' + sizes + '~',
  price + ' Precio por Mayor',
  '',
  'Modelo ya disponible en nuestro catalogo',
  'https://fylmoda.com.ar/'
].join('\n');

return {
  json: {
    ...row,
    Producto: product,
    Color: color,
    Talles: sizes,
    Precio: price,
    Descripcion: description,
    photoUrls,
    photoCount: photoUrls.length,
    igCaption,
    fbCaption: isOferta ? fbCaptionOferta : fbCaptionNormal,
    igUserId: '17841405282710550',
    fbPageId: '1064608640244020',
    postToInstagram: isYes(row.Instagram) && photoUrls.length > 0,
    postToFacebook: isYes(row.Facebook) && photoUrls.length > 0
  }
};
